∀ (a : ℕ → ℕ),
  GRWTSK.RiemannHypothesis.BranchSequenceRealization.continuedFraction a =
    { h := 0, s := ↑fun n => { a := 1, b := ↑(a n) } }

∀ (a : ℕ → ℕ) (length : ℕ),
  GRWTSK.RiemannHypothesis.BranchFrequencyExistence.prefixSet a length =
    GRWTSK.RiemannHypothesis.BranchFrequencyExistence.tailBox a ∩ {x | ∀ n < length, (x n - ↑(a n)) * x (n + 1) = 1}
